<section class="components-page form-elements-page">
  <div class="row g-4">
    <div class="col-xl-6"><div class="card app-card component-section"><div class="card-header"><h5 class="card-title mb-0">Textarea Counter</h5></div><div class="card-body"><label class="form-label" for="textareaCounter">Bio</label><textarea class="form-control" id="textareaCounter" rows="4" maxlength="120" data-maxlength-counter placeholder="Tell something about yourself...">IndigoAdmin is a clean admin template.</textarea><div class="form-text text-end"><span data-maxlength-current>0</span>/120</div></div></div></div>
    <div class="col-xl-6"><div class="card app-card component-section"><div class="card-header"><h5 class="card-title mb-0">Password Toggle</h5></div><div class="card-body form-stack"><label class="form-label" for="passwordToggle">Password</label><div class="input-group"><input class="form-control" id="passwordToggle" type="password" value="admin123" data-password-toggle-input><button class="btn btn-outline-primary" type="button" data-password-toggle="passwordToggle"><i class="bi bi-eye"></i></button></div></div></div></div>
  </div>
  <div class="row g-4"><div class="col-xl-6"><div class="card app-card component-section"><div class="card-header"><h5 class="card-title mb-0">Clipboard</h5></div><div class="card-body form-stack"><label class="form-label" for="clipboardInput">Input value</label><div class="input-group"><input class="form-control" id="clipboardInput" type="text" value="indigoadmin.local/template"><button class="btn btn-primary" type="button" data-copy-target="clipboardInput">Copy</button></div><small class="text-app-secondary" data-copy-feedback>Ready to copy.</small></div></div></div><div class="col-xl-6"><div class="card app-card component-section"><div class="card-header"><h5 class="card-title mb-0">Input Mask</h5></div><div class="card-body form-stack"><div><label class="form-label" for="maskPhone">Phone</label><input class="form-control" id="maskPhone" type="text" data-phone-mask placeholder="(555) 000-0000"></div><div><label class="form-label" for="maskCard">Credit Card</label><input class="form-control" id="maskCard" type="text" data-card-mask placeholder="0000 0000 0000 0000"></div></div></div></div></div>
  <div class="card app-card component-section"><div class="card-header"><h5 class="card-title mb-0">Autosize Textarea</h5></div><div class="card-body"><textarea class="form-control" rows="2" data-autosize-textarea placeholder="Type long content here...">This textarea grows as content gets longer.</textarea></div></div>
</section>